/**
 * search.js - Client-side search for the Jekyll blog
 * Loads search.json (generated by Jekyll) and provides real-time filtering
 * as the user types in the sidebar search input.
 */
(function() {
  'use strict';

  var posts = [];
  var searchInput = document.getElementById('search-input');
  var searchResults = document.getElementById('search-results');

  if (!searchInput || !searchResults) return;

  // Load the search index from Jekyll-generated JSON
  fetch('/search.json')
    .then(function(response) { return response.json(); })
    .then(function(data) {
      posts = data;
    })
    .catch(function(err) {
      console.error('Failed to load search index:', err);
    });

  // Filter posts by search query and render results
  function doSearch(query) {
    searchResults.innerHTML = '';

    if (!query || query.length < 2) {
      searchResults.style.display = 'none';
      return;
    }

    var q = query.toLowerCase();
    var matches = posts.filter(function(post) {
      return post.title.toLowerCase().indexOf(q) !== -1 ||
             (post.excerpt && post.excerpt.toLowerCase().indexOf(q) !== -1) ||
             (post.categories && post.categories.some(function(cat) {
               return cat.toLowerCase().indexOf(q) !== -1;
             }));
    });

    if (matches.length === 0) {
      searchResults.style.display = 'block';
      searchResults.innerHTML = '<div class="search-no-result">无结果</div>';
      return;
    }

    searchResults.style.display = 'block';
    var html = '<ul>';
    matches.slice(0, 20).forEach(function(post) {
      html += '<li><a href="' + post.url + '">' + escapeHtml(post.title) + '</a>';
      if (post.date) {
        html += ' <span class="search-date">[' + post.date + ']</span>';
      }
      html += '</li>';
    });
    html += '</ul>';
    searchResults.innerHTML = html;
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  // Debounced search on input
  var timer;
  searchInput.addEventListener('input', function() {
    clearTimeout(timer);
    timer = setTimeout(function() {
      doSearch(searchInput.value);
    }, 200);
  });

  // Close results when clicking outside
  document.addEventListener('click', function(e) {
    if (!searchInput.contains(e.target) && !searchResults.contains(e.target)) {
      searchResults.style.display = 'none';
    }
  });

  // Keyboard shortcut: focus search on Ctrl+K or /
  document.addEventListener('keydown', function(e) {
    if ((e.ctrlKey && e.key === 'k') || (e.key === '/' && !isInputFocused())) {
      e.preventDefault();
      searchInput.focus();
    }
  });

  function isInputFocused() {
    var tag = document.activeElement ? document.activeElement.tagName : '';
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
  }
})();
